<?php require_once 'auth.php';requiereAdmin();$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){$n=trim($_POST['nombre']??'');$u=trim($_POST['usuario']??'');$p=$_POST['password']??'';$r=$_POST['rol']??'empleado';if($n&&$u&&strlen($p)>=8&&in_array($r,['administrador','empleado','cliente'],true)){try{$q=$conexion->prepare('INSERT INTO usuario(nombre,usuario,password,rol) VALUES(?,?,?,?)');$q->execute([$n,$u,password_hash($p,PASSWORD_DEFAULT),$r]);$msg='Usuario creado.';}catch(Throwable $t){$msg='No se pudo crear. Puede que el usuario ya exista.';}}else $msg='Completa los datos y usa una contraseña de 8 caracteres mínimo.';}$rows=$conexion->query('SELECT idUsuario,nombre,usuario,rol FROM usuario ORDER BY idUsuario DESC')->fetchAll();encabezado('Usuarios y empleados');alerta($msg);?><div class="form-card"><h2>Crear cuenta</h2><form method="post" class="form-grid"><label>Nombre<input name="nombre" required></label><label>Usuario<input name="usuario" required></label><label>Contraseña<input type="password" name="password" minlength="8" required></label><label>Tipo de cuenta<select name="rol"><option value="empleado">Empleado</option><option value="administrador">Administrador</option><option value="cliente">Cliente</option></select></label><button class="btn">Crear usuario</button></form></div><h2>Cuentas registradas</h2><div class="table-wrap"><table><tr><th>Nombre</th><th>Usuario</th><th>Rol</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['nombre'])?></td><td><?=e($r['usuario'])?></td><td><?=e($r['rol'])?></td></tr><?php endforeach;?></table></div><?php pie();?>